<?php require 'partials.php';$db=db();$pitch=$db->query("SELECT name,team,ROUND(SUM(rl),2) rl,SUM(runs_allowed) runs_allowed,SUM(earned_runs) earned_runs,COUNT(DISTINCT game_id) games FROM pitchers GROUP BY name,team ORDER BY team,name")->fetchAll();$bat=$db->query("SELECT name,team,SUM(h) h,SUM(tb) tb,SUM(ab) ab,SUM(rbi) rbi,COUNT(DISTINCT game_id) games FROM batters GROUP BY name,team ORDER BY team,name")->fetchAll();$mvps=$db->query("SELECT g.game_no,g.play_date,g.team1,g.team2,m.name,m.team,m.notes FROM mvp m JOIN games g ON g.id=m.game_id WHERE m.name<>'' ORDER BY g.play_date,g.play_time")->fetchAll();header_html('Player statistics','stats');?><section class="card"><h1>Individual performance summary</h1><p>Totals are calculated from all game records entered by the tournament administrator.</p></section><section class="card"><h2>Pitching</h2><div class="table"><table><thead><tr><th>Name</th><th>Team</th><th>Games</th><th>RL</th><th>Runs allowed</th><th>ER / PGL</th></tr></thead><tbody><?php foreach($pitch as $x):?><tr><td><b><?=h($x['name'])?></b></td><td><?=h($x['team'])?></td><td><?=$x['games']?></td><td><?=$x['rl']?></td><td><?=$x['runs_allowed']?></td><td><?=$x['earned_runs']?></td></tr><?php endforeach?></tbody></table></div></section><section class="card"><h2>Batting</h2><div class="table"><table><thead><tr><th>Name</th><th>Team</th><th>Games</th><th>H</th><th>TB</th><th>AB</th><th>RBI</th></tr></thead><tbody><?php foreach($bat as $x):?><tr><td><b><?=h($x['name'])?></b></td><td><?=h($x['team'])?></td><td><?=$x['games']?></td><td><?=$x['h']?></td><td><?=$x['tb']?></td><td><?=$x['ab']?></td><td><?=$x['rbi']?></td></tr><?php endforeach?></tbody></table></div></section><section class="card"><h2>Match MVPs</h2><?php if(!$mvps):?><p class="muted">No MVP has been published yet.</p><?php endif;foreach($mvps as $m):?><p><b>Game <?=$m['game_no']?> · <?=h($m['name'])?></b> <span class="muted"><?=h($m['team'])?> · <?=h($m['team1'])?> vs <?=h($m['team2'])?></span><br><?=nl2br(h($m['notes']))?></p><?php endforeach?></section><?php footer_html();?>